using System;
using System.Linq;
using CashflowChains.City;
using CashflowChains.Economy;
namespace CashflowChains.Empire {
 public sealed partial class EmpireEngine {
  CityState RequiredCity(EmpireAccount a)=>a.City??throw new InvalidOperationException("Open your permanent city first");
  static CityOperatingPlan OperatingPlan(BalanceConfig c,EmpireAccount a,long now){var city=a.City;return new CityOperatingPlan{Region=city.Region,HousingRules=c.City.Revision>=3?2:c.City.Revision>=2?1:0,Payables=city.Payables,Day=city.Day,GridTier=city.GridTier,StartAt=now,FinishAt=checked(now+c.City.DaySeconds(city.Day)),CashAvailable=a.Economy.Amount("CASH"),Loans=city.Loans.Select(l=>l.Copy()).ToArray(),Partner=city.Partner,Sponsor=city.Sponsor,PartnerEndsDay=city.PartnerEndsDay,SponsorEndsDay=city.SponsorEndsDay,Properties=city.Properties.Where(p=>p.Level>0).Select(p=>{var copy=p.Copy();if(copy.PendingX>=0){copy.X=copy.PendingX;copy.Y=copy.PendingY;copy.PendingX=copy.PendingY=-1;}return copy;}).ToArray(),Inventory=a.Economy.Balances.Where(b=>c.City.Goods.Any(g=>g.Id==b.ItemId)||b.ItemId=="WOOD").Select(b=>new ItemAmount(b.ItemId,b.Earned+b.Purchased)).ToArray()};}
  public CommandReceipt OpenCity(long now)=>Command("permanent-city-charter-v1","founding-city-v1","city-charter","founding-allocation",now,(a,t)=>{if(a.City!=null)throw new InvalidOperationException("City already exists");a.City=new CityState{DemographicsVersion=config.Revision>=6?1:0};if(config.Revision<6||a.Businesses.Any(b=>b.Id=="home"&&b.Level>0)||a.Construction.Any(j=>j.BusinessId=="home"))a.City.Properties.Add(new CityProperty{Id=a.City.NextPropertyId++,Kind="home",X=1,Y=1,Level=a.Construction.Any(j=>j.BusinessId=="home")?(a.Businesses.FirstOrDefault(b=>b.Id=="home")?.Level??0):Math.Max(1,a.Businesses.FirstOrDefault(b=>b.Id=="home")?.Level??0)});foreach(var old in a.Businesses.Where(b=>b.Id!="home"&&(b.Level>0||a.Construction.Any(j=>j.BusinessId==b.Id))).OrderBy(b=>b.Id,StringComparer.Ordinal)){var definition=config.Business(old.Id);var type=config.City.Business(definition.Recipe);int cell=Enumerable.Range(0,16).First(n=>!a.City.Properties.Any(p=>p.X==n%4&&p.Y==n/4));a.City.Properties.Add(new CityProperty{Id=a.City.NextPropertyId++,Kind=type.Kind,Level=old.Level,X=cell%4,Y=cell/4,Staff=type.BaseStaff});}foreach(var old in a.Businesses.Where(b=>b.Level>0)){var waiting=a.Construction.FirstOrDefault(j=>j.BusinessId==old.Id);long through=waiting!=null?Math.Min(now,waiting.FinishAt):now;var earned=ProductionPolicy.Quote(config,old,Math.Max(old.ProducedAt,through),EmpireBenefits.Bonus(config,a,"production-bp"),EmpireBenefits.Bonus(config,a,"storage-bp"));if(earned.Amount>0)t.Grant(earned.ItemId,earned.Amount);old.ProducedAt=Math.Max(old.ProducedAt,through);old.Carry=earned.Carry;}foreach(var pending in a.Construction){string recipe=config.Business(pending.BusinessId).Recipe;var property=a.City.Properties.First(p=>p.Kind==recipe);a.City.Jobs.Add(new CityBuildingJob{Id=pending.Id,PropertyId=property.Id,TargetLevel=pending.TargetLevel,StartedAt=pending.StartedAt,FinishAt=pending.FinishAt,Seconds=(int)(pending.FinishAt-pending.StartedAt)});}t.Grant("CASH",config.City.StarterCash);t.Grant("BEANS",6);t.Grant("CUPS",12);t.Grant("WOOD",12);t.Grant("STEEL",6);});
  public CommandReceipt EnterExistingCity(long now)=>Command("city-region-entry-v1","existing-region-v1","city-context","regional-entry",now,(a,t)=>{var city=RequiredCity(a);city.Region=1;city.EarnedCashflow=a.Economy.Ledger.Where(l=>l.ItemId=="CASH"&&(l.CorrelationId??"").StartsWith("city-day-settle:",StringComparison.Ordinal)).GroupBy(l=>l.CorrelationId).Sum(g=>Math.Max(0,g.Sum(l=>l.Delta)));CityCareer.Advance(city,null);});
  public CityDayResult ForecastCity(){lock(gate){var a=state.Copy();RequiredCity(a);a=ProjectNextCityDay(a);return CityDayModel.Forecast(config.City,OperatingPlan(config,a,Math.Max(1,a.Economy.LastTrustedAt)));}}
  public CityDayResult CurrentCityDay(){lock(gate){var city=RequiredCity(state);var report=city.Trading==null?ForecastCity():CityDayModel.Forecast(config.City,city.Trading);if(city.Trading!=null)report.LoanDue=city.Loans.Sum(l=>Math.Min(l.Remaining,city.Trading.Loans.FirstOrDefault(old=>old.Id==l.Id)?.Due(city.Day)??0));return report;}}
  public CommandReceipt RenameCity(string id,string name,long now){string clean=(name??"").Trim();if(clean.Length<1||clean.Length>28||clean.Any(char.IsControl))throw new ArgumentException("Use 1–28 visible characters");return Command(id,clean,"city-identity","rename",now,(a,t)=>RequiredCity(a).Name=clean);}
  public CommandReceipt BuildCity(string id,string kind,int x,int y,long now)=>Command(id,kind+":"+x+":"+y,"city-construction","build-cost",now,(a,t)=>{var city=RequiredCity(a);var d=config.City.Business(kind);if(city.Region>=2&&!CityMetropolis.Vacant(x,y))throw new InvalidOperationException("This address already has an owner. Choose an advertised asset or rare vacant outskirts land.");if(city.Region==0&&config.Revision>=6&&!city.Properties.Any(p=>p.Kind=="cafe")){string next=city.Properties.Any(p=>p.Kind=="home")?"cafe":"home";if(kind!=next)throw new InvalidOperationException("Found your city with one house,then open its first cafe before adding more buildings.");}if(city.Jobs.Count>=city.BuilderSlots)throw new InvalidOperationException("Your builder is occupied. Plan elsewhere or let the current project finish.");if(x<0||y<0||x>=city.Width||y>=city.Height||city.Properties.Any(p=>p.X==x&&p.Y==y||p.PendingX==x&&p.PendingY==y))throw new InvalidOperationException("Choose an empty owned plot");if(!CityRegion.Unlocked(city,d,city.Population(config.City)))throw new InvalidOperationException("This business needs day "+d.UnlockDay+" and "+d.UnlockPopulation+" residents");int workers=city.Properties.Where(p=>p.Open).Sum(p=>CityWorkforce.Staff(config.City.Business(p.Kind),p));if(d.BaseStaff>0&&workers+d.BaseStaff>city.Workers(config.City))throw new InvalidOperationException("Develop housing for more local workers before adding this operation");foreach(var material in d.BuildMaterials)t.Spend(material.ItemId,material.Quantity);t.Spend("CASH",d.BuildCash);var property=new CityProperty{Id=city.NextPropertyId++,Kind=kind,X=x,Y=y,Level=0,Staff=d.BaseStaff};city.Properties.Add(property);int duration=city.Properties.Count<=3?Math.Min(d.BuildSeconds,city.Properties.Count<=2?3:8):d.BuildSeconds;city.Jobs.Add(new CityBuildingJob{Id=id,PropertyId=property.Id,TargetLevel=1,Seconds=duration,StartedAt=now,FinishAt=checked(now+duration)});});
  public CommandReceipt UpgradeCity(string id,int propertyId,long now)=>Command(id,propertyId.ToString(),"city-construction","upgrade-cost",now,(a,t)=>{var city=RequiredCity(a);if(city.Region==0&&config.Revision>=6&&!city.Properties.Any(b=>b.Kind=="cafe"&&b.Level>0))throw new InvalidOperationException("Open your first cafe before developing more capacity");var p=city.Properties.Find(b=>b.Id==propertyId)??throw new ArgumentException("Unknown property");if(p.Level<1||p.Level>=5||city.Jobs.Count>=city.BuilderSlots||city.Jobs.Any(j=>j.PropertyId==propertyId))throw new InvalidOperationException("This upgrade is not available or your builder is occupied");var d=config.City.Business(p.Kind);foreach(var material in d.BuildMaterials)t.Spend(material.ItemId,checked(material.Quantity*(p.Level+1)));t.Spend("CASH",checked(d.BuildCash*(p.Level+1)));city.Jobs.Add(new CityBuildingJob{Id=id,PropertyId=p.Id,TargetLevel=p.Level+1,Seconds=d.BuildSeconds*(p.Level+1),StartedAt=now,FinishAt=checked(now+d.BuildSeconds*(p.Level+1))});});
  public CommandReceipt FinishCityBuild(string projectId,long now)=>Command("city-finish:"+projectId,projectId,"city-construction","complete",now,(a,t)=>{var city=RequiredCity(a);var job=city.Jobs.Find(j=>j.Id==projectId)??throw new ArgumentException("Unknown construction");if(now<job.FinishAt)throw new InvalidOperationException("Construction is still running");city.Properties.Find(p=>p.Id==job.PropertyId).Level=job.TargetLevel;CashflowChains.Engagement.InvestorProgress.Record(a,config.Investor,"city-finish:"+projectId,job.Acquisition?"acquisition":"upgrade",now);city.Jobs.Remove(job);if(city.Region>0)CityCareer.Advance(city,null);});
  public CommandReceipt MoveCityProperty(string id,int propertyId,int x,int y,long now)=>Command(id,propertyId+":"+x+":"+y,"city-planning","move",now,(a,t)=>{var city=RequiredCity(a);var p=city.Properties.Find(b=>b.Id==propertyId)??throw new ArgumentException("Unknown property");if(p.AcquiredFrom>0)throw new InvalidOperationException("An acquired property stays at its address. Develop it or buy another asset.");if(city.Region>=2&&!CityMetropolis.Vacant(x,y))throw new InvalidOperationException("This address belongs to another owner");if(x<0||y<0||x>=city.Width||y>=city.Height||city.Properties.Any(b=>b.Id!=p.Id&&(b.X==x&&b.Y==y||b.PendingX==x&&b.PendingY==y)))throw new InvalidOperationException("Choose an empty owned plot");if(city.Trading==null){p.X=x;p.Y=y;p.PendingX=p.PendingY=-1;}else{p.PendingX=x;p.PendingY=y;}});
  public CommandReceipt SetCityPrice(string id,int propertyId,int basisPoints,long now)=>Command(id,propertyId+":"+basisPoints,"city-management","pricing",now,(a,t)=>{var city=RequiredCity(a);var p=city.Properties.Find(b=>b.Id==propertyId)??throw new ArgumentException("Unknown property");if(config.City.Business(p.Kind).Sales==0||basisPoints!=8000&&basisPoints!=10000&&basisPoints!=12500)throw new ArgumentException("Choose economy,standard or premium pricing");p.PriceBasisPoints=basisPoints;});
  public CommandReceipt SetCityOpen(string id,int propertyId,bool open,long now)=>Command(id,propertyId+":"+open,"city-management","opening",now,(a,t)=>{var p=RequiredCity(a).Properties.Find(b=>b.Id==propertyId)??throw new ArgumentException("Unknown property");p.Open=open;});
  public CommandReceipt ExpandCity(string id,bool east,long now)=>Command(id,east?"east":"south","city-land","expansion",now,(a,t)=>{var city=RequiredCity(a);if(city.Region>0&&!city.Properties.Any(p=>p.Level>0))throw new InvalidOperationException("Complete your first investment before expanding your portfolio");if(city.Region==0&&config.Revision>=6&&!city.Properties.Any(p=>p.Kind=="cafe"&&p.Level>0))throw new InvalidOperationException("Open your first cafe before buying more land");if((east?city.Width:city.Height)>=config.City.MaxSize)throw new InvalidOperationException("This city has reached its authored boundary");long cost=checked(city.Width*city.Height*10L);t.Spend("CASH",cost);if(east)city.Width=Math.Min(config.City.MaxSize,city.Width+2);else city.Height=Math.Min(config.City.MaxSize,city.Height+2);});
  public CommandReceipt StartCityDay(long now){lock(gate){var city=RequiredCity(state);int day=city.Day;var existing=state.Economy.Receipts.Find(r=>r.CommandId=="city-day-start:"+day);if(existing!=null)return existing.Copy();var frozen=OperatingPlan(config,state,now);return Command("city-day-start:"+day,day+"|"+frozen.Fingerprint(),"city-trading","open-day",now,(a,t)=>{var c=RequiredCity(a);if(c.Trading!=null||!(c.Region>0?c.Properties.Any(p=>p.Level>0&&p.Open):c.Properties.Any(p=>p.Kind=="cafe"&&p.Level>0)))throw new InvalidOperationException("Complete an owned asset before starting trade");foreach(var p in c.Properties)if(p.PendingX>=0){p.X=p.PendingX;p.Y=p.PendingY;p.PendingX=p.PendingY=-1;}c.Trading=frozen.Copy();});}}
  public CommandReceipt SettleCityDay(int day,long now)=>Command("city-day-settle:"+day,day.ToString(),"city-trading","settle-day",now,(a,t)=>{var city=RequiredCity(a);var plan=city.Trading;if(plan==null||plan.Day!=day||now<plan.FinishAt)throw new InvalidOperationException("The trading day is still running");var report=CityDayModel.Forecast(config.City,plan);long cashBefore=t.Available("CASH");report.LoanDue=city.Loans.Sum(l=>Math.Min(l.Remaining,plan.Loans.FirstOrDefault(old=>old.Id==l.Id)?.Due(day)??0));foreach(var resource in report.Resources){long incoming=checked(resource.Produced+resource.Imported),outgoing=checked(resource.Consumed+resource.Exported+resource.Spilled);if(incoming>0)t.Grant(resource.ItemId,incoming);if(outgoing>0)t.Spend(resource.ItemId,outgoing);}if(report.Revenue>0)t.Grant("CASH",report.Revenue);long due=checked(report.Bills+report.ImportBills+report.Tax+city.Payables),paid=Math.Min(t.Available("CASH"),due);if(paid>0)t.Spend("CASH",paid);city.Payables=due-paid;foreach(var loan in city.Loans){var original=plan.Loans.FirstOrDefault(l=>l.Id==loan.Id);long scheduled=original==null?0:Math.Min(loan.Remaining,original.Due(day)),repayment=Math.Min(scheduled,t.Available("CASH"));if(repayment>0){t.Spend("CASH",repayment);loan.Remaining-=repayment;loan.Repaid+=repayment;}loan.Arrears=Math.Min(loan.Remaining,scheduled-repayment);}city.LastDayRevenue=report.Revenue;city.LastDayBills=report.Bills+report.ImportBills+report.Tax;city.LastDayNet=t.Available("CASH")-cashBefore;if(city.LastDayNet>0)CashflowChains.Engagement.InvestorProgress.Record(a,config.Investor,"city-day-settle:"+day,"profit",now);city.LifetimeRevenue=checked(city.LifetimeRevenue+report.Revenue);city.LastClosedAt=plan.FinishAt;city.Trading=null;city.Day++;if(city.Region>0){city.EarnedCashflow=checked(city.EarnedCashflow+Math.Max(0,city.LastDayNet));CityCareer.Advance(city,report);}});
  public CommandReceipt ImproveCityGrid(string id,long now)=>Command(id,"grid","city-utilities","grid-capacity",now,(a,t)=>{var city=RequiredCity(a);if(city.Region>0&&!city.Properties.Any(p=>p.Level>0))throw new InvalidOperationException("Complete your first investment before buying extra utility capacity");if(city.GridTier>=5)throw new InvalidOperationException("Maximum authored grid connection");t.Spend("CASH",city.GridTier*200L);city.GridTier++;});
 }
